import{_ as t,H as a,f as i,i as l}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"35 | 压测报告：怎样写出一份让老板满意的报告？","description":"","frontmatter":{},"headers":[{"level":2,"title":"压测目标","slug":"压测目标","link":"#压测目标","children":[]},{"level":2,"title":"压测范围","slug":"压测范围","link":"#压测范围","children":[]},{"level":2,"title":"系统架构图","slug":"系统架构图","link":"#系统架构图","children":[{"level":3,"title":"系统技术栈","slug":"系统技术栈","link":"#系统技术栈","children":[]},{"level":3,"title":"系统逻辑架构图","slug":"系统逻辑架构图","link":"#系统逻辑架构图","children":[]},{"level":3,"title":"系统部署架构图","slug":"系统部署架构图","link":"#系统部署架构图","children":[]}]},{"level":2,"title":"硬件环境","slug":"硬件环境","link":"#硬件环境","children":[]},{"level":2,"title":"基础数据","slug":"基础数据","link":"#基础数据","children":[{"level":3,"title":"铺底数据","slug":"铺底数据","link":"#铺底数据","children":[]}]},{"level":2,"title":"系统改造","slug":"系统改造","link":"#系统改造","children":[]},{"level":2,"title":"压测设计","slug":"压测设计","link":"#压测设计","children":[]},{"level":2,"title":"监控设计","slug":"监控设计","link":"#监控设计","children":[]},{"level":2,"title":"结果整理","slug":"结果整理","link":"#结果整理","children":[]},{"level":2,"title":"结论","slug":"结论","link":"#结论","children":[{"level":3,"title":"容量场景","slug":"容量场景","link":"#容量场景","children":[]},{"level":3,"title":"稳定性场景","slug":"稳定性场景","link":"#稳定性场景","children":[]},{"level":3,"title":"异常场景","slug":"异常场景","link":"#异常场景","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]}],"relativePath":"全链路压测实战30讲/35-压测报告：怎样写出一份让老板满意的报告？.md","filePath":"全链路压测实战30讲/35-压测报告：怎样写出一份让老板满意的报告？.md","lastUpdated":1779818655000}'),n={name:"全链路压测实战30讲/35-压测报告：怎样写出一份让老板满意的报告？.md"};function E(s,e,r,o,p,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="_35-压测报告-怎样写出一份让老板满意的报告" tabindex="-1">35 | 压测报告：怎样写出一份让老板满意的报告？ <a class="header-anchor" href="#_35-压测报告-怎样写出一份让老板满意的报告" aria-label="Permalink to &quot;35 | 压测报告：怎样写出一份让老板满意的报告？&quot;">​</a></h1><p>你好，我是高楼。</p><p>在一个性能项目中，我觉得有三类文档是必须要存在的，那就是性能方案、调优报告和性能报告，它们分别代表了我们在项目实施前、实施中、实施后三个阶段的工作表现。而我们只要看看性能报告，大概率就可以知道一个项目做得如何了。</p><p>性能报告是非常重要的一份文档，它不仅要给性能方案中提出的问题一个准确的答复，也就是明确测试目的有没有达到，还要告诉非技术型领导，这个系统能不能支撑正常的业务运行。所以性能报告通常会有两种形式：Word版和PPT版。Word版是给技术人看的，PPT版是给领导看的。</p><p>但是，现在大部分人写的性能报告都只是应付一下流程，除了告诉别人“这个系统我检查完了”，好像也没有什么实质性的作用。为什么这么说呢？原因有下面几点：</p><ul><li>没有明确的可不可以上线的结论。</li></ul><p>这一点至关重要。我收集了几个结论型的描述语句给你看看。</p><blockquote><p>经过多轮的性能测试及调优，系统在部分方面达到了设计需求，可以满足当前部分业务需求，但还未达到最佳性能状态，仍存在可调优的点。</p></blockquote><blockquote><p>测试含风险通过。</p></blockquote><blockquote><p>CPU用了80%、内存用了90%，TPS达到1000，95%响应时间是500ms。</p></blockquote><p>类似这样的描述可以说是数不胜数。总结一下就是只有模糊的描述，没有明确的结论。有人说，CPU使用率80%不算是明确的结论吗？那是肯定不能算的。</p><p>结论首先要和方案中的目标对应上，你的结论应该是，目标有没有达到。可惜的是很多方案连写的目标都是模糊的，那就导致结论也是没法精确的。</p><p>另外，结论还要和场景对应上，其中最重要的就是容量、稳定性和异常场景。有人说，咦，你不是一直说四类场景吗？怎么不要基准场景了？ 在结论处，我们要描述的是整个项目对线上的系统运行有什么明确的支撑，我觉得基准场景可描述可不描述。但容量、稳定性、异常是必须要描述的，因为我们的目标就是要回答线上是否能正常运行的问题。</p><ul><li>没有明确的性能上限原因的证据。</li></ul><p>每一个系统都有性能的上限。通常我们给出的是 <strong>稳定运行的最大TPS值</strong>。而报告中，要描述出来的是为什么系统只能达到这个TPS值。</p><p>如果是因为指标只需要这么多，那硬件资源还有多少可用的水位；如果是某类硬件资源（CPU、IO、内存、网络、存储等）用到了上限，那就会有非常明确的证据；如果是因为系统设计导致的上限、因为参数配置导致的上限…那也都会有明确的证据。</p><p>唯独没有描述证据是不行的。你要是说“我的系统只能支持1000TPS，但是为啥只能支撑1000TPS，我不知道”，这肯定是不行的。</p><ul><li>没有生产运维的配置数据。</li></ul><p>作为性能项目，在明确上面两点的基础之上，我们还一定要告诉生产运维如何配置。比如说：最大最小线程数、超时时间、熔断限流规则等等各类参数。有多少这样的配置项呢？这就要参考我们的性能分析决策树对应的性能配置树了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/70da8df80c48636fe2f3d243fd27d97e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/70da8df80c48636fe2f3d243fd27d97e.jpg" alt="图片"></a></p><p>我把配置树的思维导图放在了上面，展开了其中一部分给你参考一下。</p><p>在一个具体的项目中，如果全取默认值，倒也简单了，你可以直接告诉运维都取默认值就可以了。不过但凡有值的变动，你都应该记录下来给到运维。关于这一部分你可以参考我上一个专栏的 <a href="https://time.geekbang.org/column/article/379841" target="_blank" rel="noreferrer">第30讲《如何确定生产系统配置？》</a>。 在这个专栏中我们就不展开了，不然就重复了。</p><p>那接下来，关键的问题来了。针对我们这个专栏，压测报告应该怎么写呢？压测的报告中的很多内容跟压测方案是一一对应的，所以我在报告中也会把相应的内容列出来并给出解释。如果你不记得方案了，可以回去看看 <a href="https://time.geekbang.org/column/article/428497" target="_blank" rel="noreferrer">第3讲</a>。</p><h2 id="压测目标" tabindex="-1">压测目标 <a class="header-anchor" href="#压测目标" aria-label="Permalink to &quot;压测目标&quot;">​</a></h2><blockquote><ol><li>根据经典的电商下单流程，测试当前系统的单接口最大容量。</li><li>录制真实的线上流量，回放压测流量，充分利用当前服务器资源，找到当前系统的性能瓶颈并优化，最终达到最佳容量状态。</li><li>结合稳定性场景，做到精准的容量规划，给服务做限流降级提供数据上的参考。</li><li>结合异常场景，实践并判断当前系统中的异常情况对线上产生的影响。</li></ol></blockquote><p>显然，上面的每一条我们都是实现了的。第一条对应的是第29讲基准场景；第二条对应的是第30和31讲的容量场景；第三条对应的是第32讲的稳定性场景；第四条对应第33讲的异常场景。</p><h2 id="压测范围" tabindex="-1">压测范围 <a class="header-anchor" href="#压测范围" aria-label="Permalink to &quot;压测范围&quot;">​</a></h2><blockquote><p>通过梳理核心压测链路，即电商下单主流程，可确定压测范围，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/92ebe3c285b977df01ca8029c4f08bf3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/92ebe3c285b977df01ca8029c4f08bf3.jpg" alt="图片"></a></p></blockquote><p>我们在编写脚本时就是对应这10个接口的。</p><h2 id="系统架构图" tabindex="-1">系统架构图 <a class="header-anchor" href="#系统架构图" aria-label="Permalink to &quot;系统架构图&quot;">​</a></h2><h3 id="系统技术栈" tabindex="-1">系统技术栈 <a class="header-anchor" href="#系统技术栈" aria-label="Permalink to &quot;系统技术栈&quot;">​</a></h3><blockquote><p>微服务框架：Spring Cloud 、Spring Cloud Alibaba</p><p>容器+MVC 框架：Spring Boot</p><p>认证和授权框架：Spring Security OAuth2</p><p>ORM 框架：MyBatis</p><p>数据层代码生成：MyBatisGenerator</p><p>MyBatis 物理分页插件：PageHelper</p><p>文档生产工具：Knife4j</p><p>搜索引擎：Elasticsearch</p><p>消息队列：RabbitMQ</p><p>分布式缓存：Redis</p><p>NoSQL 数据库：MongoDB</p><p>应用容器引擎：Docker</p><p>数据库连接池：Druid</p><p>对象存储：OSS、MinIO</p><p>JWT 登录支持：JWT</p><p>日志收集、处理、转发：LogStash</p><p>日志队列和缓冲：Kafka</p><p>日志采集：Filebeat</p><p>可视化分析与展示：Kibana</p><p>简化对象封装工具：Lombok</p><p>全局事务管理框架：Seata</p><p>应用容器管理平台：Kubernetes</p><p>服务保护：Sentinel</p><p>分布式链路追踪系统：Zipkin</p><p>基础资源监控： Promethues</p><p>容器级链路监控： Weave Scope</p><p>可视化看板：Grafana</p></blockquote><h3 id="系统逻辑架构图" tabindex="-1">系统逻辑架构图 <a class="header-anchor" href="#系统逻辑架构图" aria-label="Permalink to &quot;系统逻辑架构图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/260377ac4775cb97ecf9bd6bfce962b3.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/260377ac4775cb97ecf9bd6bfce962b3.jpg" alt="图片"></a></p><h3 id="系统部署架构图" tabindex="-1">系统部署架构图 <a class="header-anchor" href="#系统部署架构图" aria-label="Permalink to &quot;系统部署架构图&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/2f032901efyy2d9f9e3df8f123e8534b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/2f032901efyy2d9f9e3df8f123e8534b.png" alt="图片"></a></p><p>这些显然就是我们测试的基础信息了，这一点不会有偏差，因为我们的压测就是在这样的架构中做的。</p><h2 id="硬件环境" tabindex="-1">硬件环境 <a class="header-anchor" href="#硬件环境" aria-label="Permalink to &quot;硬件环境&quot;">​</a></h2><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/d32a2d780e8937350dd47bfdb93c2c40.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/d32a2d780e8937350dd47bfdb93c2c40.jpg" alt="图片"></a></p><p>在压测方案中，我们规划的硬件资源是8台服务器，但我们最后用到的硬件不止8台，中间我们又多加了四台8C16G的机器，所以总共是12台。</p><h2 id="基础数据" tabindex="-1">基础数据 <a class="header-anchor" href="#基础数据" aria-label="Permalink to &quot;基础数据&quot;">​</a></h2><h3 id="铺底数据" tabindex="-1">铺底数据 <a class="header-anchor" href="#铺底数据" aria-label="Permalink to &quot;铺底数据&quot;">​</a></h3><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/7d3e9e1e45032b88989ab65723f886b5.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/7d3e9e1e45032b88989ab65723f886b5.jpg" alt="图片"></a></p><p>这是原始的铺底数据，在场景执行的过程中，产生的数据还有很多，在容量评估那一讲，我们也有截图表示。</p><h2 id="系统改造" tabindex="-1">系统改造 <a class="header-anchor" href="#系统改造" aria-label="Permalink to &quot;系统改造&quot;">​</a></h2><p>这里我们要重点说一下了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/0828fe104b2e231974e117054502b18f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/0828fe104b2e231974e117054502b18f.jpg" alt="图片"></a></p><p>但是要说明一点，这里提到的时间成本是在你比较熟练的情况下需要的时间。如果需要重新学习这些技术，那估计就不是两三个月的事情了。但是不管怎么说，我觉得全链路的改造成本真的不算高，而且也并不高深。</p><h2 id="压测设计" tabindex="-1">压测设计 <a class="header-anchor" href="#压测设计" aria-label="Permalink to &quot;压测设计&quot;">​</a></h2><p>这里我只摘了压测方案中的关键内容过来。</p><blockquote><p>对于性能场景，我们认为它必须满足两个条件：连续和递增，所以在这次的全链路压测执行过程中，我们会把这两点应用到下面的业务场景中。</p></blockquote><blockquote><p>在 RESAR 全链路压测中，性能场景只需要四类，执行顺序依次为：基准场景、容量场景、稳定性场景和异常场景。</p><p>除了这四类性能场景外，再没有其他类型的场景了。在每一个场景分类中，我们都可以设计多个具体的场景来覆盖完整的业务。</p></blockquote><p>在执行过程中，我是完全按照这个思路来做的，这也是很多性能测试人员纠结的点，他们不知道这四类场景是否可以覆盖住所有的性能需求。但是请不要再纠结啦，在我的职业生涯中，还没有什么需求是可以逃到这四类场景之外的。 反而是那些拿“压力测试”“负载测试”“极限测试”等之类的幌子设置的场景最终无法给出明确的结论。</p><h2 id="监控设计" tabindex="-1">监控设计 <a class="header-anchor" href="#监控设计" aria-label="Permalink to &quot;监控设计&quot;">​</a></h2><p>下面两个图就足够说明我们在这个项目中的监控设计了，并且从文章中给出的各类的监控截图也可以看得出来，图里面的东西几乎都用到了，我们也没有偷工减料。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/160a542429b73ddf415e508866c46fb1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/160a542429b73ddf415e508866c46fb1.jpg" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/b587489008c4ba1c41dcea5bbf144b7f.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/b587489008c4ba1c41dcea5bbf144b7f.jpg" alt="图片"></a></p><p>现在就要来说说输出的内容了。</p><h2 id="结果整理" tabindex="-1">结果整理 <a class="header-anchor" href="#结果整理" aria-label="Permalink to &quot;结果整理&quot;">​</a></h2><p>在结果整理这一步，我是坚决反对用表格的。我认为直接帖压力工具或监控工具的截图即可，因为表格表达不出趋势。这里你可以直接看第29-33讲，把截图帖出来就行。比如：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/4e0220aa3382d5f4fb7714ef0f1e1578.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/4e0220aa3382d5f4fb7714ef0f1e1578.png" alt="图片"></a></p><p>这一张压力工具的趋势图就可以准确说明容量场景能跑到多大。</p><p>关于资源的截图，因为它太多了，所以我建议你帖几个全局监控的图即可。毕竟这里只是要说明一下，不是在分析过程，不用太详细。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>好，现在重点的来了。针对每个和生产有关的场景，我们要给出最终的结论。</p><h3 id="容量场景" tabindex="-1">容量场景 <a class="header-anchor" href="#容量场景" aria-label="Permalink to &quot;容量场景&quot;">​</a></h3><p>在容量场景中我们知道，系统达到了1650的最大稳定的TPS。而我们一开始的目标是1350。目标显然是达到了，可以 <strong>通过</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/f0a3e5b9c34143852e92ayy2066e4fe2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/f0a3e5b9c34143852e92ayy2066e4fe2.png" alt="图片"></a></p><h3 id="稳定性场景" tabindex="-1">稳定性场景 <a class="header-anchor" href="#稳定性场景" aria-label="Permalink to &quot;稳定性场景&quot;">​</a></h3><p>业务累计量我们定了一个500万的小目标，最后跑到了680万。结论显然也是 <strong>通过</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/fa7ddeb4a8a80a53320a0c49df0e15ab.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%85%A8%E9%93%BE%E8%B7%AF%E5%8E%8B%E6%B5%8B%E5%AE%9E%E6%88%9830%E8%AE%B2/images/475351/fa7ddeb4a8a80a53320a0c49df0e15ab.png" alt="图片"></a></p><h3 id="异常场景" tabindex="-1">异常场景 <a class="header-anchor" href="#异常场景" aria-label="Permalink to &quot;异常场景&quot;">​</a></h3><p>我们只模拟了两个异常的场景，应该说做得非常不全面。对一个专栏来说，为了说明逻辑倒也足够了。但对一个项目来说，那显然是远远不够的。所以在这个专栏的报告中，我认为异常场景的结论是 <strong>不通过</strong>。</p><p>在真实的项目中，你可以把我们在异常场景那一节中所提到的各个层级的异常场景都覆盖一遍，只有这样做才算是真正的通过。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>对于性能项目来说，性能测试人员需要给出明确的通过或者不通过的结论，另外还要给出清晰的生产配置建议，关于如何确定配置值，前面我们也给出了相应的链接。</p><p>在这节课所讲的性能报告中呢，我们必须明确说明项目所使用的硬件、软件、数据、压力策略、监控策略等等内容，因为看报告的人没必要再把压测方案找过来跟报告一起对着看，那太麻烦了。</p><p>同时，给出结果整理也是必须的，这是所有执行过程中最精华的部分。虽然你只有一两张好看的截图放在那里，但那背后是一个个辛酸的调优故事。</p><p>最后呢，我们还要给出一个结论，这是我一直强调的。这个结论首先要有数据的直接对比，其次要有能不能上线的直接说明。在报告中，模棱两可的话绝不许出现，没有结论的数据也绝不能出现。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>​学完这节课，请你思考两个问题：</p><ol><li>你觉得性能报告的重点是什么呢？</li><li>你觉得你写过的性能报告有没有问题呢？如果有，是什么？</li></ol><p>这是我们这一次、也是最后一次思考题，欢迎你在留言区与我交流讨论。</p>',83)])])}const g=t(n,[["render",E]]);export{c as __pageData,g as default};
